Tool response:
Tool: create_flight
Description: Create Flight
Parameters:
    {
      "type": "object",
      "properties": {
        "flight_number": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Flight Number"
        },
        "aircraft_id": {
          "type": "integer",
          "title": "Aircraft Id"
        },
        "origin_airport_id": {
          "type": "integer",
          "title": "Origin Airport Id"
        },
        "destination_airport_id": {
          "type": "integer",
          "title": "Destination Airport Id"
        },
        "departure_datetime_utc": {
          "type": "string",
          "title": "Departure Datetime Utc"
        },
        "arrival_datetime_utc": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Arrival Datetime Utc"
        },
        "flight_type": {
          "type": "string",
          "enum": [
            "charter",
            "scheduled",
            "private",
            "cargo",
            "ferry"
          ],
          "title": "Flight Type",
          "default": "charter"
        },
        "status": {
          "type": "string",
          "enum": [
            "scheduled",
            "boarding",
            "departed",
            "en_route",
            "landed",
            "cancelled",
            "delayed"
          ],
          "title": "Status",
          "default": "scheduled"
        },
        "passenger_count": {
          "type": "integer",
          "title": "Passenger Count",
          "default": 0
        },
        "baggage_weight_lbs": {
          "type": "number",
          "title": "Baggage Weight Lbs",
          "default": 0.0
        },
        "special_requests": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Special Requests"
        }
      },
      "required": [
        "aircraft_id",
        "origin_airport_id",
        "destination_airport_id",
        "departure_datetime_utc"
      ]
    }

Tool response:
Tool: lookup_aircraft_by_tail_number
Description: Lookup Aircraft By Tail Number
Parameters:
    {
      "type": "object",
      "properties": {
        "tail_number": {
          "type": "string",
          "description": "The tail number of the aircraft (e.g., N123AB)",
          "title": "Tail Number"
        }
      },
      "required": [
        "tail_number"
      ]
    }

Tool response:
Tool: lookup_airport_by_icao_code
Description: Lookup Airport By Icao Code
Parameters:
    {
      "type": "object",
      "properties": {
        "icao_code": {
          "type": "string",
          "description": "The ICAO code of the airport (e.g., KJFK)",
          "title": "Icao Code"
        }
      },
      "required": [
        "icao_code"
      ]
    }
